questions.code:
env:
- name: NODE
  valueFrom: {fieldRef: {fieldPath: spec.nodeName}}

kubectl get cm app-cfg -o jsonpath='{.data}' | head
volumeMounts:
- {name: cfg, mountPath: /etc/app/app.conf, subPath: app.conf}

volumes:
- name: logs
  emptyDir: {sizeLimit: 1Gi}
resources:
  limits: {ephemeral-storage: 2Gi}

kubectl get nodes -o custom-columns=N:.metadata.name,T:.spec.taints
tolerations:
- {key: dedicated, operator: Equal, value: gpu, effect: NoSchedule}

egress:
- to:
  - namespaceSelector:
      matchLabels: {kubernetes.io/metadata.name: kube-system}
    podSelector:
      matchLabels: {k8s-app: kube-dns}
  ports:
  - {protocol: UDP, port: 53}
  - {protocol: TCP, port: 53}

kubectl get volumesnapshot snap -o jsonpath='{.status.restoreSize}'
spec:
  dataSource: {name: snap, kind: VolumeSnapshot, apiGroup: snapshot.storage.k8s.io}

volumes:
- name: cache
  emptyDir: {medium: Memory, sizeLimit: 256Mi}

volumeMounts:
- {name: tmp, mountPath: /tmp}
- {name: cache, mountPath: /var/cache/nginx}
volumes:
- {name: tmp, emptyDir: {}}
- {name: cache, emptyDir: {}}

- --audit-policy-file=/etc/kubernetes/audit/policy.yaml
- --audit-log-path=/var/log/kubernetes/audit/audit.log
volumeMounts:
- {name: audit-pol, mountPath: /etc/kubernetes/audit, readOnly: true}
- {name: audit-log, mountPath: /var/log/kubernetes/audit}

authentication:
  anonymous: {enabled: false}
  webhook: {enabled: true}
  x509: {clientCAFile: /etc/kubernetes/pki/ca.crt}
